import { booleanAttribute, ChangeDetectionStrategy, Component, computed, contentChild, effect, inject, input, model, NgModule, output, TemplateRef, untracked } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import {
    OrganizationChartCheckboxValue,
    OrganizationChartNodeCollapseEvent,
    OrganizationChartNodeExpandEvent,
    OrganizationChartNodeKeys,
    OrganizationChartNodeSelectEvent,
    OrganizationChartNodeUnSelectEvent,
    OrganizationChartPassThrough,
    OrganizationChartSelectionMode,
    OrgChartNode
} from 'primeng/types/organizationchart';
import { OrganizationChartNode } from './organizationchart-node';
import { ORGANIZATIONCHART_INSTANCE } from './organizationchart-token';
import { OrganizationChartStyle } from './style/organizationchartstyle';

/**
 * OrganizationChart visualizes hierarchical organization data.
 * @group Components
 */
@Component({
    selector: 'p-organization-chart, p-organizationchart',
    standalone: true,
    imports: [OrganizationChartNode, BindModule],
    template: `
        @if (root()) {
            <ul [class]="cx('subtree', { root: true })" role="tree" [attr.aria-multiselectable]="selectionMode() === 'multiple' || selectionMode() === 'checkbox' ? true : undefined" [pBind]="ptm('subtree')">
                <li
                    [class]="cx('tree')"
                    role="treeitem"
                    [attr.data-level]="1"
                    [attr.aria-level]="1"
                    [attr.aria-expanded]="getAriaExpanded(root()!)"
                    [attr.aria-selected]="getAriaSelected(root()!)"
                    pOrganizationChartNode
                    [node]="root()!"
                    [root]="true"
                    [level]="1"
                    [pt]="pt"
                    [unstyled]="unstyled()"
                    [pBind]="ptm('tree')"
                ></li>
            </ul>
        }
    `,
    changeDetection: ChangeDetectionStrategy.Default,
    providers: [OrganizationChartStyle, { provide: ORGANIZATIONCHART_INSTANCE, useExisting: OrganizationChart }, { provide: PARENT_INSTANCE, useExisting: OrganizationChart }],
    host: {
        '[class]': "cx('root')",
        '[style.--px-gap-x.px]': 'gapX()',
        '[style.--px-gap-y.px]': 'gapY()'
    },
    hostDirectives: [Bind]
})
export class OrganizationChart extends BaseComponent<OrganizationChartPassThrough> {
    componentName = 'OrganizationChart';

    /**
     * An array of nested OrgChartNodes.
     * @group Props
     */
    value = input<OrgChartNode[]>();
    /**
     * Defines the selection mode.
     * @group Props
     */
    selectionMode = input<OrganizationChartSelectionMode | null>();
    /**
     * Whether the nodes can be expanded or toggled.
     * @defaultValue false
     * @group Props
     */
    collapsible = input(false, { transform: booleanAttribute });
    /**
     * Whether the nodes can be selected when a `selectionMode` is defined. Can be overridden per node with `OrgChartNode.selectable`.
     * @defaultValue true
     * @group Props
     */
    selectable = input(true, { transform: booleanAttribute });
    /**
     * Defines the gap between nodes. Can be a single number or a tuple [gapX, gapY].
     * @group Props
     */
    gap = input<number | [number, number]>(40);
    /**
     * A map of node keys whose values are `true` for the selected nodes. Two-way bindable.
     * When omitted, it is seeded from each node's `selectedByDefault` flag.
     * @group Props
     */
    selectionKeys = model<OrganizationChartNodeKeys | null>(null);
    /**
     * A map of node keys whose values are `true` for the collapsed nodes. Two-way bindable.
     * When omitted, it is seeded from each node's `collapsedByDefault` flag.
     * @group Props
     */
    collapsedKeys = model<OrganizationChartNodeKeys | null>(null);
    /**
     * Callback to invoke when a node is selected.
     * @param {OrganizationChartNodeSelectEvent} event - custom node select event.
     * @group Emits
     */
    onNodeSelect = output<OrganizationChartNodeSelectEvent>();
    /**
     * Callback to invoke when a node is unselected.
     * @param {OrganizationChartNodeUnSelectEvent} event - custom node unselect event.
     * @group Emits
     */
    onNodeUnselect = output<OrganizationChartNodeUnSelectEvent>();
    /**
     * Callback to invoke when a node is expanded.
     * @param {OrganizationChartNodeExpandEvent} event - custom node expand event.
     * @group Emits
     */
    onNodeExpand = output<OrganizationChartNodeExpandEvent>();
    /**
     * Callback to invoke when a node is collapsed.
     * @param {OrganizationChartNodeCollapseEvent} event - custom node collapse event.
     * @group Emits
     */
    onNodeCollapse = output<OrganizationChartNodeCollapseEvent>();

    /**
     * Custom toggler icon template.
     * @param {Object} context - item data.
     * @group Templates
     */
    togglerIconTemplate = contentChild<TemplateRef<any>>('togglericon', { descendants: false });

    /**
     * Custom collapse button template.
     * @param {Object} context - collapse button data.
     * @group Templates
     */
    collapseButtonTemplate = contentChild<TemplateRef<any>>('collapsebutton', { descendants: false });

    /**
     * Custom checkbox icon template for `checkbox` selection mode.
     * @param {Object} context - checkbox icon data.
     * @group Templates
     */
    checkboxIconTemplate = contentChild<TemplateRef<any>>('checkboxicon', { descendants: false });

    /**
     * Custom node template.
     * @group Templates
     */
    nodeTemplate = contentChild<TemplateRef<any>>('node', { descendants: false });

    _componentStyle = inject(OrganizationChartStyle);

    bindDirectiveInstance = inject(Bind, { self: true });

    $pcOrganizationChart = inject(ORGANIZATIONCHART_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    /**
     * The active selection map, normalized so consumers never deal with `null`.
     */
    _selectionKeys = computed<OrganizationChartNodeKeys>(() => this.selectionKeys() ?? {});

    /**
     * The active collapsed map, normalized so consumers never deal with `null`.
     */
    _collapsedKeys = computed<OrganizationChartNodeKeys>(() => this.collapsedKeys() ?? {});

    constructor() {
        super();
        effect(() => {
            const value = this.value();
            if (!value || !value.length) {
                return;
            }
            // Seed the key maps from the deprecated node defaults; reads of the key signals are untracked
            // so the effect only re-runs on value changes (and never loops when seeding writes the maps).
            untracked(() => this.syncDefaultKeyState(value));
        });
    }

    ngAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }

    root = computed(() => {
        const value = this.value();
        return value && value.length ? value[0] : null;
    });

    gapX = computed(() => {
        const g = this.gap();
        return Array.isArray(g) ? g[0] : g;
    });

    gapY = computed(() => {
        const g = this.gap();
        return Array.isArray(g) ? (g.length > 1 ? g[1] : g[0]) : g;
    });

    getTemplateForNode(_node: OrgChartNode): TemplateRef<any> | null {
        return this.nodeTemplate() ?? null;
    }

    isSelected(node: OrgChartNode): boolean {
        const key = node?.key as string;
        if (key == null) {
            return false;
        }

        const value = this._selectionKeys()[key];

        if (this.selectionMode() === 'checkbox') {
            return (value as OrganizationChartCheckboxValue)?.checked === true;
        }

        return value === true;
    }

    isPartialSelected(node: OrgChartNode): boolean {
        if (this.selectionMode() !== 'checkbox') {
            return false;
        }

        const key = node?.key as string;
        if (key == null) {
            return false;
        }

        return (this._selectionKeys()[key] as OrganizationChartCheckboxValue)?.partialChecked === true;
    }

    isCollapsed(node: OrgChartNode): boolean {
        const key = node?.key as string;
        return key != null && this._collapsedKeys()[key] === true;
    }

    getAriaExpanded(node: OrgChartNode): boolean | undefined {
        return node.children && node.children.length > 0 ? !this.isCollapsed(node) : undefined;
    }

    getAriaSelected(node: OrgChartNode): boolean | undefined {
        return this.selectionMode() ? this.isSelected(node) : undefined;
    }

    onNodeClick(event: Event, node: OrgChartNode) {
        const selectionMode = this.selectionMode();
        if (!selectionMode || node.key == null) {
            return;
        }

        const selectable = node.selectable === true || (node.selectable !== false && this.selectable());
        if (!selectable) {
            return;
        }

        if (selectionMode === 'checkbox') {
            this.onCheckboxNodeClick(event, node);
            return;
        }

        const key = node.key as string;
        const current = this._selectionKeys();
        const selected = current[key] === true;
        let next: OrganizationChartNodeKeys;

        if (selected) {
            next = selectionMode === 'single' ? {} : { ...current };
            if (selectionMode !== 'single') {
                delete next[key];
            }
            this.onNodeUnselect.emit({ originalEvent: event, node });
        } else {
            next = selectionMode === 'single' ? {} : { ...current };
            next[key] = true;
            this.onNodeSelect.emit({ originalEvent: event, node });
        }

        this.selectionKeys.set(next);
    }

    private onCheckboxNodeClick(event: Event, node: OrgChartNode) {
        const key = node.key as string;
        const next: OrganizationChartNodeKeys = { ...this._selectionKeys() };
        const selecting = (next[key] as OrganizationChartCheckboxValue)?.checked !== true;

        const descendantKeys = [key, ...this.getDescendantKeys(node)];
        for (const descendantKey of descendantKeys) {
            if (selecting) {
                next[descendantKey] = { checked: true, partialChecked: false };
            } else {
                delete next[descendantKey];
            }
        }

        const ancestorKeys = this.getAncestorKeys(key) ?? [];
        for (const ancestorKey of [...ancestorKeys].reverse()) {
            const ancestor = this.findNodeByKey(ancestorKey);
            const childKeys = ancestor?.children?.map((child) => child.key as string) ?? [];
            const allChecked = childKeys.length > 0 && childKeys.every((childKey) => (next[childKey] as OrganizationChartCheckboxValue)?.checked === true);
            const someChecked = childKeys.some((childKey) => {
                const value = next[childKey] as OrganizationChartCheckboxValue;
                return value?.checked === true || value?.partialChecked === true;
            });

            if (allChecked) {
                next[ancestorKey] = { checked: true, partialChecked: false };
            } else if (someChecked) {
                next[ancestorKey] = { checked: false, partialChecked: true };
            } else {
                delete next[ancestorKey];
            }
        }

        this.selectionKeys.set(next);

        if (selecting) {
            this.onNodeSelect.emit({ originalEvent: event, node });
        } else {
            this.onNodeUnselect.emit({ originalEvent: event, node });
        }
    }

    private findNodeByKey(key: string, nodes: OrgChartNode[] | undefined | null = this.value()): OrgChartNode | null {
        if (!nodes) {
            return null;
        }

        for (const node of nodes) {
            if (node.key === key) {
                return node;
            }

            const match = node.children ? this.findNodeByKey(key, node.children) : null;
            if (match) {
                return match;
            }
        }

        return null;
    }

    private getDescendantKeys(node: OrgChartNode): string[] {
        return (node.children ?? []).flatMap((child) => [child.key as string, ...this.getDescendantKeys(child)]);
    }

    private getAncestorKeys(key: string, nodes: OrgChartNode[] | undefined | null = this.value(), trail: string[] = []): string[] | null {
        if (!nodes) {
            return null;
        }

        for (const node of nodes) {
            if (node.key === key) {
                return trail;
            }

            const path = node.children ? this.getAncestorKeys(key, node.children, [...trail, node.key as string]) : null;
            if (path) {
                return path;
            }
        }

        return null;
    }

    onNodeToggle(event: Event, node: OrgChartNode) {
        if (node.key == null) {
            return;
        }

        const key = node.key as string;
        const next: OrganizationChartNodeKeys = { ...this._collapsedKeys() };

        if (next[key]) {
            delete next[key];
            this.onNodeExpand.emit({ originalEvent: event, node });
        } else {
            next[key] = true;
            this.onNodeCollapse.emit({ originalEvent: event, node });
        }

        this.collapsedKeys.set(next);
    }

    private syncDefaultKeyState(value: OrgChartNode[]) {
        const nodes = this.flattenNodes(value);

        if (this.collapsedKeys() == null) {
            const seeded = this.resolveCollapsedKeys(nodes);
            if (!this.isSameKeyState(this._collapsedKeys(), seeded)) {
                this.collapsedKeys.set(seeded);
            }
        }

        if (this.selectionKeys() == null) {
            const seeded = this.resolveSelectionKeys(nodes);
            if (!this.isSameKeyState(this._selectionKeys(), seeded)) {
                this.selectionKeys.set(seeded);
            }
        }
    }

    private flattenNodes(nodes: OrgChartNode[] | undefined | null): OrgChartNode[] {
        const result: OrgChartNode[] = [];
        const walk = (list?: OrgChartNode[] | null) => {
            if (!list) return;
            for (const node of list) {
                result.push(node);
                if (node.children?.length) {
                    walk(node.children);
                }
            }
        };
        walk(nodes);
        return result;
    }

    private resolveCollapsedKeys(nodes: OrgChartNode[]): OrganizationChartNodeKeys {
        const seeded: OrganizationChartNodeKeys = {};
        const chartCollapsible = this.collapsible();

        for (const node of nodes) {
            if (!node.collapsedByDefault || node.key == null) continue;

            const hasChildren = !!node.children?.length;
            const collapsible = node.collapsible === true || (node.collapsible !== false && chartCollapsible);

            if (hasChildren && collapsible) {
                seeded[node.key as string] = true;
            }
        }

        return seeded;
    }

    private resolveSelectionKeys(nodes: OrgChartNode[]): OrganizationChartNodeKeys {
        const seeded: OrganizationChartNodeKeys = {};
        const chartSelectable = this.selectable();
        const single = this.selectionMode() === 'single';
        const checkbox = this.selectionMode() === 'checkbox';

        for (const node of nodes) {
            if (!node.selectedByDefault || node.key == null) continue;

            const selectable = node.selectable === true || (node.selectable !== false && chartSelectable);
            if (!selectable) continue;

            seeded[node.key as string] = checkbox ? { checked: true, partialChecked: false } : true;

            if (single) break;
        }

        return seeded;
    }

    private isSameKeyState(current: OrganizationChartNodeKeys, next: OrganizationChartNodeKeys): boolean {
        const currentKeys = Object.keys(current || {});
        const nextKeys = Object.keys(next || {});

        if (currentKeys.length !== nextKeys.length) {
            return false;
        }

        return currentKeys.every((key) => current[key] === next[key]);
    }
}

@NgModule({
    imports: [OrganizationChart],
    exports: [OrganizationChart]
})
export class OrganizationChartModule {}
